#!/usr/bin/env python3
"""NXT CAMP Staff: ajuste visual no iPhone (rádio e caixa do termo). Uso no servidor:
  python3 nxt-staff-visual.py --verificar   # só confere
  python3 nxt-staff-visual.py               # publica, com backup"""
import base64, hashlib, os, shutil, sys, tempfile
from pathlib import Path
NXT=Path('/home/novaigre/public_html/next/camp-sbgp1-nov26')
OLD={'inscricao.html':'075692d05b45a44a1f86f1136d7cbf3e5d0d217516a35f17b395390752098011',
     'assets/inscricao.css':'dec8c5cf68055717b191cc3bcd943be0cfe946dae604e53303601f76ef9761a2'}
NEW={'inscricao.html':base64.b64decode(''),
     'assets/inscricao.css':base64.b64decode('')}
sha=lambda b:hashlib.sha256(b).hexdigest()
for rel,h in OLD.items():
    p=NXT/rel
    if not p.is_file() or p.is_symlink(): sys.exit(f'ABORTADO: arquivo ausente: {p}')
    if sha(p.read_bytes())!=h: sys.exit(f'ABORTADO: {rel} de produção mudou (sha {sha(p.read_bytes())})')
if '--verificar' in sys.argv:
    for rel,d in NEW.items(): print('OK',rel,sha(d))
    print('VERIFICADO: nada foi gravado'); sys.exit(0)
backup=Path(tempfile.mkdtemp(prefix='nib-nxt-staff-visual-',dir='/home/novaigre/nib-manutencao'))
for rel,d in NEW.items():
    p=NXT/rel; dest=backup/rel; dest.parent.mkdir(parents=True,exist_ok=True); shutil.copy2(p,dest)
    fd,tmp=tempfile.mkstemp(prefix='.nib-staff-',dir=p.parent)
    try:
        with os.fdopen(fd,'wb') as f: f.write(d)
        shutil.copymode(p,tmp); os.replace(tmp,p)
    finally:
        if os.path.exists(tmp): os.unlink(tmp)
    assert p.read_bytes()==d; print('PUBLICADO',p,sha(d))
print('BACKUP:',backup)
